<?php
require_once 'config/database.php';require_once 'includes/auth.php';require_once 'includes/functions.php';require_login();$uid=current_user()['user_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$rid=(int)$_POST['request_id'];$action=$_POST['action'];$status=$action==='accept'?'accepted':($action==='reject'?'rejected':'cancelled');$s=$pdo->prepare("UPDATE SkillRequests SET status=?,responded_at=NOW() WHERE request_id=? AND ((receiver_id=? AND status='pending') OR (sender_id=? AND status='pending'))");$s->execute([$status,$rid,$uid,$uid]);flash('success','Request updated.');redirect('requests.php');}
$s=$pdo->prepare("SELECT r.*,a.first_name sf,a.last_name sl,b.first_name rf,b.last_name rl,rs.skill_name requested_skill,os.skill_name offered_skill FROM SkillRequests r JOIN Users a ON a.user_id=r.sender_id JOIN Users b ON b.user_id=r.receiver_id JOIN Skills rs ON rs.skill_id=r.requested_skill_id JOIN Skills os ON os.skill_id=r.offered_skill_id WHERE r.sender_id=? OR r.receiver_id=? ORDER BY r.created_at DESC");$s->execute([$uid,$uid]);$rows=$s->fetchAll();$title='Requests';include 'includes/header.php';
?>
<div class="page-head"><div><div class="eyebrow">SKILL EXCHANGES</div><h1>Requests.</h1></div></div><div class="grid cards-2"><?php foreach($rows as $r):?><div class="card request"><div class="request-head"><span class="badge <?=$r['status']?>"><?=e($r['status'])?></span><small><?=e($r['created_at'])?></small></div><h3><?=e($r['sf'].' → '.$r['rf'])?></h3><p><?=e($r['requested_skill'])?> in exchange for <?=e($r['offered_skill'])?></p><p class="muted"><?=e($r['message'])?></p><?php if($r['status']==='pending'):?><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="request_id" value="<?=$r['request_id']?>"><?php if($r['receiver_id']==$uid):?><button class="btn" name="action" value="accept">Accept</button><button class="btn ghost" name="action" value="reject">Reject</button><?php else:?><button class="btn ghost" name="action" value="cancel">Cancel</button><?php endif;?></form><?php endif;?></div><?php endforeach;?></div>
<?php include 'includes/footer.php'; ?>
